export type UUID = string;

export interface User {
    id: UUID;
    name: string;
    email: string;
}

export interface Project {
    id: UUID;
    name: string;
    description: string;
    memberIds: UUID[]; // Array of user IDs
}

export type TaskStatus = "todo" | "in-progress" | "done";

export interface Task {
    id: UUID;
    title: string;
    description: string;
    status: TaskStatus;
    assigneeId: UUID | null;
    projectId: UUID;
}

export interface Comment {
    id: UUID;
    taskId: UUID;
    authorId: UUID;
    body: string;
    createdAt: string; // ISO 8601 timestamp
}

export interface Notification {
    id: UUID;
    userId: UUID;
    message: string;
    read: boolean;
    createdAt: string; // ISO 8601 timestamp
}

// Event Payloads
export interface TaskAssignedEvent {
    taskId: UUID;
    taskTitle: string;
    assigneeId: UUID;
}

export interface TaskStatusChangedEvent {
    taskId: UUID;
    taskTitle: string;
    assigneeId: UUID | null; // Assignee might be null if task was unassigned
    oldStatus: TaskStatus;
    newStatus: TaskStatus;
}

export interface CommentAddedEvent {
    commentId: UUID;
    taskId: UUID;
    taskTitle: string;
    authorId: UUID;
    authorName: string;
}

type EventCallback = (payload: any) => void;

export class EventBus {
    private subscribers: Map<string, EventCallback[]> = new Map();

    public publish(event: string, payload: any): void {
        const callbacks = this.subscribers.get(event);
        if (callbacks) {
            for (const callback of callbacks) {
                try {
                    callback(payload);
                } catch (error) {
                    console.error(`Error processing event '${event}':`, error);
                }
            }
        }
    }

    public subscribe(event: string, callback: EventCallback): void {
        if (!this.subscribers.has(event)) {
            this.subscribers.set(event, []);
        }
        this.subscribers.get(event)?.push(callback);
    }

    public unsubscribe(event: string, callback: EventCallback): void {
        const callbacks = this.subscribers.get(event);
        if (callbacks) {
            this.subscribers.set(event, callbacks.filter(cb => cb !== callback));
        }
    }
}

import { User, UUID } from '../types';
import * as crypto from 'crypto';

function generateUUID(): UUID {
    return crypto.randomUUID();
}

export class UserService {
    private users: Map<UUID, User> = new Map();

    constructor() {
        // Seed with some initial data for testing
        const user1Id = generateUUID();
        this.users.set(user1Id, { id: user1Id, name: 'Alice Smith', email: 'alice@example.com' });
        const user2Id = generateUUID();
        this.users.set(user2Id, { id: user2Id, name: 'Bob Johnson', email: 'bob@example.com' });
    }

    public create(name: string, email: string): User {
        if (!name || !email) {
            throw new Error('User name and email are required.');
        }
        const newUser: User = {
            id: generateUUID(),
            name,
            email,
        };
        this.users.set(newUser.id, newUser);
        return newUser;
    }

    public getById(id: UUID): User | undefined {
        return this.users.get(id);
    }

    public getAll(): User[] {
        return Array.from(this.users.values());
    }

    public update(id: UUID, name?: string, email?: string): User | undefined {
        const user = this.users.get(id);
        if (user) {
            if (name !== undefined) user.name = name;
            if (email !== undefined) user.email = email;
            return { ...user }; // Return a clone to prevent external modification
        }
        return undefined;
    }

    public delete(id: UUID): boolean {
        return this.users.delete(id);
    }
}

import { Project, UUID } from '../types';
import * as crypto from 'crypto';

function generateUUID(): UUID {
    return crypto.randomUUID();
}

export class ProjectService {
    private projects: Map<UUID, Project> = new Map();

    public create(name: string, description: string): Project {
        if (!name) {
            throw new Error('Project name is required.');
        }
        const newProject: Project = {
            id: generateUUID(),
            name,
            description,
            memberIds: [],
        };
        this.projects.set(newProject.id, newProject);
        return newProject;
    }

    public getById(id: UUID): Project | undefined {
        return this.projects.get(id);
    }

    public getAll(): Project[] {
        return Array.from(this.projects.values());
    }

    public update(id: UUID, name?: string, description?: string): Project | undefined {
        const project = this.projects.get(id);
        if (project) {
            if (name !== undefined) project.name = name;
            if (description !== undefined) project.description = description;
            return { ...project };
        }
        return undefined;
    }

    public delete(id: UUID): boolean {
        return this.projects.delete(id);
    }

    public addMember(projectId: UUID, userId: UUID): Project | undefined {
        const project = this.projects.get(projectId);
        if (project) {
            if (!project.memberIds.includes(userId)) {
                project.memberIds.push(userId);
                return { ...project };
            }
        }
        return undefined;
    }

    public removeMember(projectId: UUID, userId: UUID): Project | undefined {
        const project = this.projects.get(projectId);
        if (project) {
            const initialLength = project.memberIds.length;
            project.memberIds = project.memberIds.filter(id => id !== userId);
            if (project.memberIds.length < initialLength) {
                return { ...project };
            }
        }
        return undefined;
    }
}

import { Task, TaskStatus, UUID, TaskAssignedEvent, TaskStatusChangedEvent } from '../types';
import { EventBus } from '../event-bus';
import * as crypto from 'crypto';

function generateUUID(): UUID {
    return crypto.randomUUID();
}

export class TaskService {
    private tasks: Map<UUID, Task> = new Map();
    private eventBus: EventBus;

    constructor(eventBus: EventBus) {
        this.eventBus = eventBus;
    }

    public create(title: string, description: string, projectId: UUID): Task {
        if (!title || !projectId) {
            throw new Error('Task title and project ID are required.');
        }
        const newTask: Task = {
            id: generateUUID(),
            title,
            description,
            status: 'todo',
            assigneeId: null,
            projectId,
        };
        this.tasks.set(newTask.id, newTask);
        return newTask;
    }

    public getById(id: UUID): Task | undefined {
        return this.tasks.get(id);
    }

    public getByProject(projectId: UUID): Task[] {
        return Array.from(this.tasks.values()).filter(task => task.projectId === projectId);
    }

    public update(id: UUID, title?: string, description?: string): Task | undefined {
        const task = this.tasks.get(id);
        if (task) {
            if (title !== undefined) task.title = title;
            if (description !== undefined) task.description = description;
            return { ...task };
        }
        return undefined;
    }

    public delete(id: UUID): boolean {
        return this.tasks.delete(id);
    }

    public assign(taskId: UUID, assigneeId: UUID | null): Task | undefined {
        const task = this.tasks.get(taskId);
        if (task) {
            task.assigneeId = assigneeId;
            this.eventBus.publish('task.assigned', { 
                taskId: task.id,
                taskTitle: task.title,
                assigneeId: task.assigneeId
            } as TaskAssignedEvent);
            return { ...task };
        }
        return undefined;
    }

    public changeStatus(taskId: UUID, newStatus: TaskStatus): Task | undefined {
        const task = this.tasks.get(taskId);
        if (task) {
            const oldStatus = task.status;
            let validTransition = false;
            if (oldStatus === 'todo' && newStatus === 'in-progress') {
                validTransition = true;
            } else if (oldStatus === 'in-progress' && newStatus === 'done') {
                validTransition = true;
            } else if (oldStatus === newStatus) { // Allow setting to same status
                validTransition = true;
            }

            if (!validTransition) {
                throw new Error(`Invalid task status transition from ${oldStatus} to ${newStatus}`);
            }

            task.status = newStatus;

            this.eventBus.publish('task.statusChanged', {
                taskId: task.id,
                taskTitle: task.title,
                assigneeId: task.assigneeId,
                oldStatus: oldStatus,
                newStatus: newStatus,
            } as TaskStatusChangedEvent);
            return { ...task };
        }
        return undefined;
    }
}

import { Comment, UUID, CommentAddedEvent } from '../types';
import { EventBus } from '../event-bus';
import * as crypto from 'crypto';

function generateUUID(): UUID {
    return crypto.randomUUID();
}

export class CommentService {
    private comments: Map<UUID, Comment> = new Map();
    private eventBus: EventBus;

    constructor(eventBus: EventBus) {
        this.eventBus = eventBus;
    }

    public create(taskId: UUID, authorId: UUID, authorName: string, body: string): Comment {
        if (!taskId || !authorId || !body) {
            throw new Error('Task ID, author ID, and comment body are required.');
        }
        const newComment: Comment = {
            id: generateUUID(),
            taskId,
            authorId,
            body,
            createdAt: new Date().toISOString(),
        };
        this.comments.set(newComment.id, newComment);

        this.eventBus.publish('comment.added', {
            commentId: newComment.id,
            taskId: newComment.taskId,
            taskTitle: '', // Placeholder, router/calling service needs to fill this if needed
            authorId: newComment.authorId,
            authorName: authorName,
        } as CommentAddedEvent);

        return newComment;
    }

    public getById(id: UUID): Comment | undefined {
        return this.comments.get(id);
    }

    public getByTask(taskId: UUID): Comment[] {
        return Array.from(this.comments.values()).filter(comment => comment.taskId === taskId);
    }

    public delete(id: UUID): boolean {
        return this.comments.delete(id);
    }
}
